import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;
public class Main {public static void main(String[] args)throws IOException{Path folder=Paths.get("sample-logs");Files.createDirectories(folder);Files.write(folder.resolve("one.txt"),List.of("INFO started","ERROR disk","INFO ended"));Files.write(folder.resolve("two.txt"),List.of("WARN memory","ERROR network"));long total=0,matches=0;String keyword="ERROR";try(DirectoryStream<Path> stream=Files.newDirectoryStream(folder,"*.txt")){for(Path file:stream){long count=0;try(BufferedReader r=Files.newBufferedReader(file)){String line;while((line=r.readLine())!=null){count++;total++;if(line.contains(keyword))matches++;}}BasicFileAttributes a=Files.readAttributes(file,BasicFileAttributes.class);System.out.println(file.getFileName()+": lines="+count+", size="+a.size()+" bytes");}}System.out.println("Total lines: "+total);System.out.println("Lines containing "+keyword+": "+matches);}}
